import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { Subscription } from 'rxjs';
import { AuthService } from '../auth/auth.service';
import { UserProfile, UserProfileResponse } from '../auth/model/userProfile';
import { FormService } from '../service/form.service';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss']
})
export class HeaderComponent implements OnInit {

  SHOW_CONFIRM_SAVE_ICON_TIMEOUT_MS = 5_000;

  displayName = '';
  showLogoutModal = false;
  showDraftModal = false;
  showConfirmSaveModal = false;
  showConfirmSaveIcon = false;
  confirmSaveModalAlreadyShown = false;
  showConfirmSaveIconTimeout: any = null;
  isAuthenticated = false;
  subscriptions: Subscription[] = [];
  profile: UserProfile = new UserProfileResponse();
  provisionalSavingAllowed = false;

  @Input() showSaveDraftLink = false;
  @Output() loadDraftEvent = new EventEmitter<string>();
  @Output() saveDraftEvent = new EventEmitter<void>();
  @Output() logoutEvent = new EventEmitter<void>();

  constructor(private authService: AuthService, private formService: FormService) { }

  async ngOnInit(): Promise<any> {
    this.subscriptions.push(
      this.authService.userProfileObservable.subscribe((userProfile) => {
        this.profile = userProfile;
        this.displayName = userProfile.displayName;
      }),
      this.authService.isAuthenticatedObservable.subscribe((check) => {
        this.isAuthenticated = check;
      })
    );
    const formConfig = this.formService.getFormConfig();
    if (formConfig) {
      this.provisionalSavingAllowed = formConfig.provisionalSavingAllowed;
    }
  }

  ngOnDestroy() {
    clearTimeout(this.showConfirmSaveIconTimeout);
  }

  logout(): void {
    this.authService.logout();
    this.logoutEvent.emit();
  }

  setShowLogoutModal(showLogoutModal: boolean): void {
    this.showLogoutModal = showLogoutModal;
  }

  setShowDraftModal(showDraftModal: boolean): void {
    this.showDraftModal = showDraftModal;
  }

  setShowConfirmSaveModal(showConfirmSaveModal: boolean): void {
    this.showConfirmSaveModal = showConfirmSaveModal;
  }

  loadDraft(): void {
    this.loadDraftEvent.emit();
    this.showDraftModal = false;
  }

  saveDraft(): void {
    this.saveDraftEvent.emit();

    if (this.confirmSaveModalAlreadyShown) {
      if (this.showConfirmSaveIconTimeout != null) {
        clearTimeout(this.showConfirmSaveIconTimeout);
      }

      this.showConfirmSaveIcon = true;
      this.showConfirmSaveIconTimeout = setTimeout(() => {
        this.showConfirmSaveIcon = false;
      }, this.SHOW_CONFIRM_SAVE_ICON_TIMEOUT_MS);
    } else {
      this.setShowConfirmSaveModal(true);
      this.confirmSaveModalAlreadyShown = true;
    }
  }
}
