import { Component, OnInit } from '@angular/core';
import { getConfig } from 'src/app/app-config';
import { AuthService } from '../auth.service';

@Component({
    selector: 'app-home',
    templateUrl: './loginfailed.component.html',
    styleUrls: ['./loginfailed.component.scss']
})
export class LoginfailedComponent implements OnInit {

    constructor(private authService: AuthService) { }

    ngOnInit(): void {
        this.authService.removeLocalUserdata(true);
    }

    back(): void {
        window.location.href = getConfig().defaultCallbackUrl;
    }
}
