import { Component, OnInit } from '@angular/core';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { getConfig } from '../app-config';
import { AppConstants } from '../constants/app.constants';
import { FormConfig } from '../service/form-config';
import { FormService } from '../service/form.service';
import {AuthService} from '../auth/auth.service';

declare var $: any;

@Component({
  selector: 'app-paymentsuccessful',
  templateUrl: './paymentsuccessful.component.html',
  styleUrls: ['./paymentsuccessful.component.scss']
})
export class PaymentsuccessfulComponent implements OnInit {

  pdfurl: string = '';
  reference: string = '';
  amount: number = 0;
  formTitle: string = '';
  uuid: string = '';

  constructor(public route: ActivatedRoute,
              private titleService: Title,
              private router: Router,
              private formService: FormService,
              private authService: AuthService
  ) {
    this.route.queryParams
        .subscribe(params => {
          this.amount = parseFloat(params.amount);
          this.reference = params.reference;
          this.formTitle = params.formTitle;
          this.uuid = params.uuid
        });
  }

  ngOnInit(): void {
    this.titleService.setTitle(AppConstants.TITLE_PREFIX + 'Betaling geslaagd');
    const secured = this.authService.isAuthenticated();
    this.pdfurl = this.formService.getPdfUrl(secured, this.uuid, this.reference, this.formTitle)
  }

  public currencyFormat(): string {
    return (
        this.amount
            .toFixed(2) // always two decimal digits
            .replace('.', ',') // replace decimal point character with ,
            .replace(/(\d)(?=(\d{3})+(?!\d))/g, '$1.')
    ); // use . as a separator
  }

  public openPDF(pdfUrl: string): void {
    window.open(pdfUrl);
  }

  getCallbackUrl(): string {
    return this.formService.getCallbackUrl();
  }
}
